/**
 * 中期演示数据：章节来自项目目录《课程大纲.docx》。
 * 32 个节点为按大纲选取的演示知识点，不是用户尚未提供的原始 32 点清单。
 * 题目、文字课件和演示短片为自制内容；另接入西交工热mooc 课程 PDF 与已核对目录的 B 站网课。
 * 基本公式核对来源见同目录 CONTENT_NOTES.md。
 */
export interface Chapter { id: string; number: string; title: string; shortTitle: string; color: string; description: string }
export interface KnowledgeNode { id: string; title: string; chapterId: string; summary: string; formula?: string; formulaNote?: string; core: boolean; level: '基础' | '进阶' | '应用'; x: number; y: number }
export interface Relation { source: string; target: string; type: '前置' | '包含' | '应用' }
export type QuestionType = 'single' | 'multi' | 'judge' | 'fill'
export interface Question {
  id: string; nodeIds: string[]; chapterId: string; stem: string; options?: string[];
  answer?: number[];          // 单选/判断为单元素数组，多选为多个下标数组（fill 类型不使用）
  answers?: string[];         // 仅 fill 类型使用，按空位顺序存标准答案
  explanation: string; difficulty: '基础' | '进阶'; type?: QuestionType  // 缺省 'single'
}
export type ResourceType = 'video' | 'slides' | 'external' | 'pdf'
/** external 的 nodeIds 可为空，表示仅关联章节；pdf 的 src 使用 /static/courseware/ 路径。 */
export interface Resource { id: string; title: string; type: ResourceType; nodeIds: string[]; chapterId: string; duration: string; description: string; color: string; theme: string; cover?: string; src?: string; slides?: { title: string; body: string[]; formula?: string }[]; url?: string; course?: string; source?: string; author?: string; featured?: boolean }
/** 四类资源在页面上的统一名称、图标与访问方式；各页面按 ResourceType 取用，不再各写一套二选一判断。 */
export const resourceTypeLabel: Record<ResourceType, string> = { video: '演示短片', slides: '知识课件', external: '网课资源', pdf: '课程 PDF' }
export const resourceTypeIcon: Record<ResourceType, string> = { video: 'video', slides: 'file', external: 'link', pdf: 'file' }
export const resourceTypeHint: Record<ResourceType, string> = { video: '可离线播放', slides: '在线阅读', external: '站外打开', pdf: '新标签页阅读' }
export const resourceTypeEyebrow: Record<ResourceType, string> = { video: 'WATCH & UNDERSTAND', slides: 'READ & CONNECT', external: 'EXPLORE FURTHER', pdf: 'COURSE PDF' }
/** 仅接受 http/https 绝对地址；外部资源缺少合法链接时页面显示「链接待补充」且不可点击。 */
export function isExternalUrl(url?: string) { return typeof url === 'string' && /^https?:\/\/[^\s]+$/i.test(url.trim()) }

