export const nodes: KnowledgeNode[] = [
  { id: 'energy-use', title: '热能及其利用', chapterId: 'ch0', summary: '工程热力学研究热能与其他形式能量的转换规律，以及工质的热力性质。', core: true, level: '基础', x: 75, y: 80 },
  { id: 'system', title: '热力系统', chapterId: 'ch1', summary: '根据边界上的质量交换区分闭口系统与开口系统；孤立系统与外界既无质量交换，也无能量交换。', core: true, level: '基础', x: 225, y: 85 },
  { id: 'state', title: '状态与状态参数', chapterId: 'ch1', summary: '压力、温度、比容等描述平衡状态。状态参数的变化只取决于初、终状态。', formula: String.raw`v = \frac{V}{m}`, formulaNote: '比容 v 的 SI 单位为 m³/kg；状态方程中的压力为绝对压力、温度为 K。', core: true, level: '基础', x: 345, y: 60 },
  { id: 'process', title: '热力过程', chapterId: 'ch1', summary: '工质由一个状态变化到另一个状态。可逆过程要求过程中无耗散，且系统与外界均可恢复原状。', core: true, level: '基础', x: 325, y: 155 },
  { id: 'cycle', title: '热力循环', chapterId: 'ch1', summary: '工质经过一系列过程回到初态。循环中热力学能变化为零，净吸热等于净输出功。', formula: String.raw`\oint \delta Q = \oint \delta W`, formulaNote: '采用吸热为正、系统对外做功为正的约定。', core: true, level: '基础', x: 195, y: 185 },
  { id: 'first-law', title: '热力学第一定律', chapterId: 'ch2', summary: '能量不能凭空产生或消失。闭口系统的能量变化由热量和功共同决定。', formula: String.raw`\Delta U = Q - W`, formulaNote: '闭口系统，忽略宏观动能和势能变化；Q 为系统吸热，W 为系统对外做功。', core: true, level: '基础', x: 510, y: 145 },
  { id: 'internal-energy', title: '热力学能', chapterId: 'ch2', summary: '热力学能 U 是状态参数，反映系统内部微观运动及相互作用所对应的能量。理想气体的 U 仅随温度变化。', formula: String.raw`\Delta u = \int_{T_1}^{T_2} c_v(T)\,\mathrm{d}T`, formulaNote: '理想气体；积分上下限为 T₁、T₂。定比热时 Δu = cᵥ(T₂ − T₁)。', core: true, level: '基础', x: 455, y: 55 },
  { id: 'enthalpy', title: '焓', chapterId: 'ch2', summary: '焓将热力学能与压力、体积的乘积组合起来，便于描述流动工质携带的能量。', formula: String.raw`h = u + pv`, formulaNote: 'h、u 为单位质量量；采用 kPa 与 m³/kg 时，pv 的单位为 kJ/kg。', core: true, level: '基础', x: 605, y: 65 },
  { id: 'steady-flow', title: '稳定流动能量方程', chapterId: 'ch2', summary: '稳定流动时控制体内各处参数不随时间变化，可对进出口焓、动能、势能、传热及轴功列能量平衡。', formula: String.raw`q-w_s=h_2-h_1+\frac{c_2^2-c_1^2}{2}+g(z_2-z_1)`, formulaNote: '单进单出、每单位质量；能量统一使用 J/kg，速度为 m/s；wₛ 以向外输出为正。', core: true, level: '进阶', x: 635, y: 195 },
  { id: 'ideal-gas', title: '理想气体状态方程', chapterId: 'ch3', summary: '理想气体模型忽略分子自身体积及分子间作用力，适合在相应条件下近似分析实际气体。', formula: String.raw`pv = RT`, formulaNote: 'p 为绝对压力，T 用 K；R 为该气体的比气体常数。', core: true, level: '基础', x: 790, y: 65 },
  { id: 'heat-capacity', title: '理想气体比热容', chapterId: 'ch3', summary: '定容比热容描述热力学能随温度的变化，定压比热容描述焓随温度的变化。', formula: String.raw`c_p - c_v = R`, formulaNote: '理想气体；比热比 κ = cₚ/cᵥ。比热容通常随温度变化。', core: true, level: '基础', x: 925, y: 135 },
  { id: 'steam', title: '水与水蒸气', chapterId: 'ch3', summary: '水的相变涉及饱和液体、湿蒸汽、干饱和蒸汽及过热蒸汽。湿蒸汽干度为气相质量分数。', formula: String.raw`x = \frac{m_{\mathrm{vap}}}{m_{\mathrm{vap}}+m_{\mathrm{liq}}}`, formulaNote: '干度仅用于饱和两相混合物；物性通常查水蒸气表。', core: true, level: '进阶', x: 780, y: 190 },
  { id: 'isothermal', title: '定温过程', chapterId: 'ch4', summary: '理想气体定温过程的热力学能不变。若仅有容积功，则吸热量等于对外做功。', formula: String.raw`W = mRT\ln\frac{V_2}{V_1}`, formulaNote: '定量理想气体的可逆定温过程；T 为 K，膨胀时 W > 0。', core: true, level: '基础', x: 800, y: 310 },
  { id: 'isochoric', title: '定容过程', chapterId: 'ch4', summary: '体积不变时容积功为零。闭口系统仅有容积功、且忽略动能势能变化时，吸热用于增加热力学能。', formula: String.raw`W_v = 0,\quad Q = \Delta U`, formulaNote: 'Q = ΔU 的表达式还要求没有电功、轴功等其他功形式。', core: true, level: '基础', x: 925, y: 260 },
  { id: 'isobaric', title: '定压过程', chapterId: 'ch4', summary: '可逆定压过程的容积功等于压力与体积变化量之积。闭口系统仅有容积功时，吸热等于焓增。', formula: String.raw`W = p(V_2-V_1),\quad Q = \Delta H`, formulaNote: '忽略宏观动能和势能变化；功式使用一致单位。', core: true, level: '基础', x: 935, y: 410 },
  { id: 'adiabatic', title: '可逆绝热过程', chapterId: 'ch4', summary: '绝热表示没有热量交换。可逆绝热过程等熵；理想气体绝热膨胀对外做功时温度下降。', formula: String.raw`pv^{\kappa} = \mathrm{const},\quad \kappa = \frac{c_p}{c_v}`, formulaNote: '幂指数为 κ；此关系限于定比热理想气体的可逆绝热过程。绝热本身不等于等熵。', core: true, level: '进阶', x: 785, y: 440 },
  { id: 'second-law', title: '热力学第二定律', chapterId: 'ch5', summary: '第二定律揭示过程的方向与限制。循环热机不能仅从单一热源吸热，并将其全部转化为功而不产生其他影响。', core: true, level: '基础', x: 465, y: 285 },
  { id: 'carnot', title: '卡诺循环', chapterId: 'ch5', summary: '由两个可逆定温过程和两个可逆绝热过程组成，是同一对恒温热源之间热机效率的理论上限。', formula: String.raw`\eta_C = 1 - \frac{T_L}{T_H}`, formulaNote: 'Tₕ、Tₗ 必须用 K，且 Tₕ > Tₗ > 0。', core: true, level: '进阶', x: 620, y: 335 },
  { id: 'entropy', title: '熵与熵增原理', chapterId: 'ch5', summary: '熵是状态参数。孤立系统的总熵不减少：可逆过程不变，不可逆过程增加。一般系统的熵也可因向外传熵而减少。', formula: String.raw`\mathrm{d}S=\frac{\delta Q_{\mathrm{rev}}}{T},\quad S_{\mathrm{gen}}\geq 0`, formulaNote: '第一式按可逆途径计算熵变；不能直接将不可逆过程的 δQ/T 当作 dS。', core: true, level: '进阶', x: 475, y: 410 },
  { id: 'exergy', title: '能量贬值与㶲', chapterId: 'ch5', summary: '能量守恒并不保证做功能力不变。相对于给定环境，不可逆性使可用能减少。', formula: String.raw`E_{x,\mathrm{dest}} = T_0 S_{\mathrm{gen}}`, formulaNote: 'T₀ 为给定环境绝对温度；能量本身并未消失。', core: true, level: '进阶', x: 625, y: 455 },
  { id: 'real-gas', title: '实际气体与压缩因子', chapterId: 'ch6', summary: '实际气体受分子体积与相互作用影响，偏离理想气体模型，可用压缩因子表征偏差。', formula: String.raw`Z = \frac{pv}{RT}`, formulaNote: '理想气体 Z = 1；实际气体的 Z 随状态和工质改变。', core: true, level: '进阶', x: 310, y: 275 },
  { id: 'general-relations', title: '热力学一般关系式', chapterId: 'ch6', summary: '对组成不变的简单可压缩系统，基本关系将热力学能、焓、熵与状态参数联系起来。', formula: String.raw`\mathrm{d}u=T\mathrm{d}s-p\mathrm{d}v,\quad \mathrm{d}h=T\mathrm{d}s+v\mathrm{d}p`, formulaNote: '适用于平衡状态之间的物性关系，不要求实际过程可逆。', core: true, level: '进阶', x: 315, y: 385 },
  { id: 'nozzle', title: '喷管与流速', chapterId: 'ch7', summary: '喷管将工质的部分焓转化为动能。绝热、无轴功且位差可忽略时，总焓保持不变。', formula: String.raw`h_1+\frac{c_1^2}{2}=h_2+\frac{c_2^2}{2}`, formulaNote: 'h 用 J/kg，速度 c 用 m/s；若 h 用 kJ/kg，动能项需除以 1000。', core: true, level: '应用', x: 95, y: 335 },
  { id: 'throttling', title: '绝热节流', chapterId: 'ch7', summary: '流体通过阀门或多孔塞产生压降。稳定、绝热、无轴功且动能势能变化可忽略时，节流前后焓相等。', formula: String.raw`h_1 = h_2`, formulaNote: '节流通常不可逆；实际气体节流后的温度可能降低、升高或不变。', core: true, level: '应用', x: 110, y: 455 },
  { id: 'compressor', title: '压气机与级间冷却', chapterId: 'ch8', summary: '压气机消耗轴功以提高气体压力。对给定进气状态和总压比，合理的多级压缩与级间冷却可降低压缩耗功。', core: true, level: '应用', x: 270, y: 505 },
  { id: 'otto', title: '奥托循环', chapterId: 'ch9', summary: '空气标准奥托循环由两个定容过程和两个等熵过程组成，用于分析火花点火式内燃机的理想循环。', formula: String.raw`\eta = 1 - \frac{1}{r^{\kappa-1}}`, formulaNote: '幂指数为 κ − 1；定比热空气标准模型，r 为压缩比，κ = cₚ/cᵥ。', core: true, level: '应用', x: 400, y: 545 },
  { id: 'brayton', title: '布雷顿循环', chapterId: 'ch9', summary: '理想布雷顿循环由两个定压过程和两个等熵过程组成，是分析燃气轮机装置的基本模型。', core: true, level: '应用', x: 460, y: 640 },
  { id: 'rankine', title: '朗肯循环', chapterId: 'ch10', summary: '由泵、锅炉、汽轮机与凝汽器构成，利用水和水蒸气的相变完成蒸汽动力循环。', formula: String.raw`\eta = \frac{w_{\mathrm{turbine}}-w_{\mathrm{pump}}}{q_{\mathrm{in}}}`, formulaNote: '各项按单位质量取正的大小；应计入泵耗功。', core: true, level: '应用', x: 625, y: 585 },
  { id: 'refrigeration', title: '蒸气压缩制冷', chapterId: 'ch11', summary: '压缩机、冷凝器、节流装置与蒸发器构成基本循环。制冷系数衡量单位耗功带来的制冷量。', formula: String.raw`\mathrm{COP}_R = \frac{Q_L}{W_{\mathrm{in}}}`, formulaNote: 'Qₗ、W输入 均取正的大小；COP 是性能系数，可以大于 1。', core: true, level: '应用', x: 815, y: 555 },
  { id: 'heat-pump', title: '逆卡诺循环与热泵', chapterId: 'ch11', summary: '热泵关注向高温端供热。逆卡诺循环给出相同恒温热源条件下制冷或供热性能系数的上限。', formula: String.raw`\mathrm{COP}_{R,C}=\frac{T_L}{T_H-T_L},\quad \mathrm{COP}_H=\mathrm{COP}_R+1`, formulaNote: '温度用 K；第二式适用于同一循环、同一工况的供热与制冷性能系数。', core: true, level: '应用', x: 935, y: 640 },
  { id: 'mixture', title: '理想气体混合物', chapterId: 'ch12', summary: '理想气体混合物中，各组分按混合温度和总体积单独占有时的压力称为分压力，总压等于分压力之和。', formula: String.raw`p = \sum_i p_i`, formulaNote: '道尔顿分压定律适用于理想气体混合物。', core: true, level: '进阶', x: 95, y: 585 },
  { id: 'humid-air', title: '湿空气与含湿量', chapterId: 'ch12', summary: '湿空气由干空气与水蒸气构成。含湿量以每单位质量干空气所含的水蒸气质量表示，可结合焓湿图分析空调过程。', formula: String.raw`d = \frac{m_{\mathrm{water\ vapor}}}{m_{\mathrm{dry\ air}}}`, formulaNote: '常用单位 kg/kg(干空气) 或 g/kg(干空气)；含湿量与相对湿度是不同参数。', core: true, level: '应用', x: 245, y: 640 },
]

